args.submissionSource:
export function dedupeSorted(arr) {
  if (arr === null || arr === undefined) return [];
  if (arr.length === 0) return [];
  if (arr.length === 1) return arr;

  const result = [arr[0]];
  for (let i = 1; i < arr.length; i++) {
    if (arr[i] > arr[i - 1]) {
      result.push(arr[i]);
    }
  }
  return result;
}

