import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { spawnSync } from "node:child_process";
import path from "node:path";
import crypto from "node:crypto";

export async function gate({ referenceDir, submissionDir }) {
  try {
    const pinnedPath = path.join(referenceDir, "pinned-test-cases.txt");
    let pinnedSrc;
    try {
      pinnedSrc = readFileSync(pinnedPath, "utf8");
    } catch (e) {
      return { accept: false, reason: "could not read pinned-test-cases.txt: " + String(e) };
    }

    const expectedCount = (pinnedSrc.match(/\btest\s*\(/g) || []).length;
    if (expectedCount === 0) {
      return { accept: false, reason: "could not find any pinned test cases to run" };
    }

    const answerPath = path.join(submissionDir, "answer.mjs");
    if (!existsSync(answerPath)) {
      return { accept: false, reason: "submission does not provide answer.mjs" };
    }

    const nonce = crypto.randomBytes(16).toString("hex");
    const resultsPath = path.join(referenceDir, "gate-results-" + nonce + ".json");
    const harnessPath = path.join(referenceDir, "gate-harness-" + nonce + ".mjs");

    const lines = [];
    lines.push("import assert from 'node:assert/strict';");
    lines.push("import { writeFileSync } from 'node:fs';");
    lines.push("import { pathToFileURL } from 'node:url';");
    lines.push("const resultsPath = " + JSON.stringify(resultsPath) + ";");
    lines.push("const answerPath = " + JSON.stringify(answerPath) + ";");
    lines.push("const expectedCount = " + expectedCount + ";");
    lines.push("const pinnedSrc = " + JSON.stringify(pinnedSrc) + ";");
    lines.push("const REAL_EXIT = process.exit.bind(process);");
    lines.push("const REAL_REALLY_EXIT = (typeof process.reallyExit === 'function') ? process.reallyExit.bind(process) : null;");
    lines.push("class FakeExitSignal extends Error {}");
    lines.push("process.exit = (code) => { throw new FakeExitSignal('submission attempted process.exit(' + code + ')'); };");
    lines.push("if (typeof process.reallyExit === 'function') { process.reallyExit = (code) => { throw new FakeExitSignal('submission attempted process.reallyExit(' + code + ')'); }; }");
    lines.push("function finish(obj) { try { writeFileSync(resultsPath, JSON.stringify(obj)); } catch (e) {} if (REAL_REALLY_EXIT) { REAL_REALLY_EXIT(0); } else { REAL_EXIT(0); } }");
    lines.push("async function main() {");
    lines.push("  let dedupeSorted;");
    lines.push("  try {");
    lines.push("    const mod = await import(pathToFileURL(answerPath).href);");
    lines.push("    dedupeSorted = mod.dedupeSorted;");
    lines.push("  } catch (e) {");
    lines.push("    return finish({ completed: true, importError: String(e && e.message || e), totalExpected: expectedCount, totalRun: 0, allPassed: false, results: [] });");
    lines.push("  }");
    lines.push("  if (typeof dedupeSorted !== 'function') {");
    lines.push("    return finish({ completed: true, importError: 'dedupeSorted is not an exported function', totalExpected: expectedCount, totalRun: 0, allPassed: false, results: [] });");
    lines.push("  }");
    lines.push("  const queue = [];");
    lines.push("  function test(name, fn) { queue.push({ name, fn }); }");
    lines.push("  try {");
    lines.push("    const registerFn = new Function('test', 'assert', 'dedupeSorted', pinnedSrc);");
    lines.push("    registerFn(test, assert, dedupeSorted);");
    lines.push("  } catch (e) {");
    lines.push("    return finish({ completed: true, registerError: String(e && e.message || e), totalExpected: expectedCount, totalRun: 0, allPassed: false, results: [] });");
    lines.push("  }");
    lines.push("  const results = [];");
    lines.push("  for (const entry of queue) {");
    lines.push("    try {");
    lines.push("      await entry.fn();");
    lines.push("      results.push({ name: entry.name, passed: true });");
    lines.push("    } catch (e) {");
    lines.push("      results.push({ name: entry.name, passed: false, error: String(e && e.message || e) });");
    lines.push("    }");
    lines.push("  }");
    lines.push("  const allPassed = results.length === expectedCount && results.every(function(r) { return r.passed; });");
    lines.push("  finish({ completed: true, totalExpected: expectedCount, totalRun: results.length, allPassed: allPassed, results: results });");
    lines.push("}");
    lines.push("main().catch(function(e) {");
    lines.push("  finish({ completed: true, uncaughtError: String(e && e.message || e), totalExpected: expectedCount, totalRun: 0, allPassed: false, results: [] });");
    lines.push("});");

    const harnessSource = lines.join("\n");
    writeFileSync(harnessPath, harnessSource, "utf8");

    const proc = spawnSync(process.execPath, [harnessPath], {
      timeout: 15000,
      killSignal: "SIGKILL",
      encoding: "utf8"
    });

    let resultsRaw;
    try {
      resultsRaw = readFileSync(resultsPath, "utf8");
    } catch (e) {
      return {
        accept: false,
        reason: "no results file produced (status=" + proc.status + ", signal=" + proc.signal + ", error=" + (proc.error ? String(proc.error) : "none") + "); the submission likely hung or terminated the process before the suite completed"
      };
    }

    let parsed;
    try {
      parsed = JSON.parse(resultsRaw);
    } catch (e) {
      return { accept: false, reason: "results file was not valid JSON; cannot trust harness output" };
    }

    if (!parsed || parsed.completed !== true) {
      return { accept: false, reason: "harness did not report completion" };
    }
    if (parsed.importError) {
      return { accept: false, reason: "failed to import submission: " + parsed.importError };
    }
    if (parsed.registerError) {
      return { accept: false, reason: "failed to register pinned tests against submission: " + parsed.registerError };
    }
    if (parsed.uncaughtError) {
      return { accept: false, reason: "uncaught error while running pinned tests: " + parsed.uncaughtError };
    }
    if (parsed.totalRun !== expectedCount) {
      return { accept: false, reason: "suite did not run to completion: ran " + parsed.totalRun + " of " + expectedCount + " pinned test cases" };
    }
    if (proc.status !== 0) {
      return { accept: false, reason: "harness process exited abnormally (status=" + proc.status + ", signal=" + proc.signal + ")" };
    }
    if (!parsed.allPassed) {
      const failed = (parsed.results || []).filter(function(r) { return !r.passed; }).map(function(r) { return r.name + ": " + (r.error || "failed"); });
      return { accept: false, reason: "pinned test cases failed: " + failed.join("; ") };
    }

    return { accept: true, reason: "all " + expectedCount + " pinned test cases executed to completion in an isolated process and passed against the submission's own dedupeSorted" };
  } catch (e) {
    return { accept: false, reason: "gate internal error: " + String(e && e.message || e) };
  }
}

